style.css:
@-moz-document regexp("https?://(www\.|m\.)?pikabu\.ru(/.*)?") {
/* Host-exact, NOT domain(): the subdomains are separate light apps this sheet only
     half-reaches. */

  /* Flip Pikabu's ~900 palette tokens at :root, plus a net for literal-colour
     surfaces. Brand and semantic hues are kept. */

  :root {
    color-scheme: dark !important;

    /* ---- Local palette ---- */
    --pk-bg: #14181d;            /* base canvas */
    --pk-surface: #1c2128;       /* elevated cards (stories, comments) */
    --pk-surface-2: #1a1f26;     /* secondary surface (inputs, chips) */
    --pk-header: #0d1117;        /* header / footer */
    --pk-border: #2a313a;        /* subtle borders */
    --pk-border-soft: #232931;   /* very subtle dividers */
    --pk-text: #e6edf3;          /* primary text */
    --pk-text-soft: #c4cdd6;     /* body text */
    --pk-text-muted: #8b949e;    /* muted / hints / placeholder */
    --pk-green: #8fd35c;          /* refined Pikabu green (brand) */
    --pk-green-hover: #a4e072;
    --pk-green-deep: #6fae44;    /* green RINGS and outlines (never under white text) */
    --pk-green-shade: #598039;   /* green FILLS that carry a white label — 4.6:1 */

    /* ---- Greyscale ramps: light end -> dark surfaces, dark end -> light text ---- */
    --color-bright-900: var(--pk-surface);
    --color-bright-800: var(--pk-surface);
    --color-linear-bright-900: var(--pk-surface);
    --color--header__bg: var(--pk-header);
    --footer-bg: var(--pk-header);

    --color-blackjack-100: var(--pk-surface);   /* was #fcfdff */
    --color-blackjack-99: var(--pk-bg);          /* was #f7f8fc */
    --color-blackjack-97: var(--pk-surface-2);   /* was #f2f3f7 */
    --color-blackjack-90: var(--pk-border);      /* was #dfe1e5 */
    --color-blackjack-75: #6b7480;
    --color-blackjack-70: var(--pk-text-muted);  /* was #aaacb2 */
    --color-blackjack-60: var(--pk-text-muted);  /* was #909299 */
    --color-blackjack-50primary: #9aa3ad;        /* was #757880 */
    --color-blackjack-30: var(--pk-text-soft);   /* was #45474d */
    --color-blackjack-18: var(--pk-text);        /* was #292a2e */
    --color-blackjack-15: var(--pk-text);        /* was #222326 */
    --color-blackjack-10: var(--pk-text);        /* was #1f2021 */

    --color-black-100: var(--pk-surface);        /* was #f9f9fb */
    --color-black-200: var(--pk-surface);        /* was #f9f9fb */
    --color-black-300: var(--pk-bg);             /* was #f7f8fc */
    --color-black-400: var(--pk-border);         /* was #e9e9e9 */
    /* NOT a surface token: black-420 is only ever a `color`, on the video-player scrim
       label. */
    --color-black-420: #e9e9e9;
    --color-black-430: var(--pk-border);         /* was #ebedf2 */
    --color-black-440: var(--pk-border);
    --color-black-500: #4a525c;                  /* was #d8dadd */
    --color-black-600: #7d8893;                  /* was #b0b3bb */
    --color-black-700: #aab3bd;                  /* was #70737b */
    --color-black-800: var(--pk-text-soft);      /* was #444850 */
    --color-black-900: var(--pk-text);           /* was #212121 */
    --color-black-920: var(--pk-text);
    --color-black-940: var(--pk-text);           /* body text was #1b1e24 */

    /* ---- Background / surface design tokens ---- */
    --s-colorBg-clear: var(--pk-surface);
    --s-colorBg-tonned: var(--pk-bg);
    --s-colorBg-stroke: var(--pk-border);
    --s-colorBg-special: #2a2718;
    --s-colorBg-popup: rgba(0, 0, 0, 0.64);

    --s-text-heading-primary: var(--pk-text);
    --s-text-paragraph-primary: var(--pk-text);
    --s-text-paragraph-secondary: var(--pk-text-soft);
    --s-text-subheading-primary: var(--pk-text);
    --s-text-label-primary: var(--pk-text-soft);
    --s-text-label-secondary: var(--pk-text-muted);
    --s-text-label-tertiary: var(--pk-text-muted);
    --user-name-text: var(--pk-text);
    /* Neutral secondary-link token, near-black by default. */
    --c-link-secondary-default: var(--pk-text-soft);

    /* ---- Inputs / textareas / comboboxes / selects ---- */
    --c-input-bgDefault: var(--pk-surface-2);
    --c-input-bgDisabled: var(--pk-bg);
    --c-input-strokeDefault: var(--pk-border);
    --c-input-textDefault: var(--pk-text-muted);
    --c-textarea-bgDefault: var(--pk-surface-2);
    --c-textarea-bgDisabled: var(--pk-bg);
    --c-textarea-strokeDefault: var(--pk-border);
    --c-textarea-textFilled: var(--pk-text);
    /* File drop-zone: panel, ring, label and both drag-over states are token-driven. */
    --c-uploader-bgDefault: var(--pk-surface-2);
    --c-uploader-bgHover: #26331c;
    --c-uploader-bgClick: #3a4d2a;
    --c-uploader-bgDisabled: var(--pk-bg);
    --c-uploader-strokeDefault: var(--pk-border);
    --c-uploader-strokeAccent: var(--pk-green-deep);
    --c-uploader-textDefault: var(--pk-text-soft);
    --c-uploader-textAccent: var(--pk-green);
    --c-uploader-textLoader: var(--pk-text-muted);
    --c-combobox-bgDefault: var(--pk-surface-2);
    --c-combobox-bgDisabled: var(--pk-bg);
    --c-combobox-content-bg: var(--pk-bg);
    --c-combobox-strokeDefault: var(--pk-border);
    --c-combobox-content-stroke: var(--pk-border);
    --c-combobox-contentDefault: var(--pk-text-muted);
    --c-combobox-contentFilled: var(--pk-text);
    --c-combobox-contentDisabled: var(--pk-text-muted);
    /* Suggestion list; only exists once the field is focused and typed into. */
    --c-combobox-list-textPrimary: var(--pk-text-soft);
    --c-combobox-list-textSecondary: var(--pk-text-muted);
    --c-combobox-list-hover: var(--pk-surface);
    --c-combobox-list-click: var(--pk-border);
    --c-combobox-searchBg: #3a4d2a;
    --c-select-main-bgDefault: var(--pk-surface-2);
    --c-select-main-bgDisabled: var(--pk-bg);
    --c-select-main-strokeDefault: var(--pk-border);
    --c-select-list-bg: var(--pk-surface);
    --c-select-list-item-text: var(--pk-text);
    /* The Select panel paints from --c-select-list-item-default (NOT -bg), portaled into
       <body> while open. */
    --c-select-list-item-default: var(--pk-surface);
    --c-select-list-item-hover: var(--pk-surface-2);
    --c-select-list-item-click: var(--pk-border);
    --c-selectBtn-bgDefault: var(--pk-surface-2);
    --c-selectBtn-bgHover: var(--pk-surface);
    --c-selectBtn-stroke: var(--pk-border);

    /* SelectBtn press state (feed topic chips) and the label colour they share. */
    --c-selectBtn-bgClick: var(--pk-border);
    --c-selectBtn-text: var(--pk-text);

    /* Header nav hover/press pill. */
    --c-navigation-horizontal-hover: var(--pk-surface);
    --c-navigation-horizontal-click: var(--pk-border);

    /* Must be dark: Pikabu's white lands ~1.9:1 on this theme's lightened brand green. */
    --c-btn-primary-textIcon: var(--pk-bg);

    /* Hover+press fill of the collapse / power-rating toggles. */
    --collapse-hover: var(--pk-border);
    --collapse-click: #39414b;

    /* The donated pill's own fill matches the .emotion-btn_donated rule below. */
    --reaction-click: var(--pk-border);
    --reaction-popover-hover: var(--pk-border);
    --reaction-popover-click: #39414b;
    --reaction-popover-active: #39414b;
    --reaction-donat-default: #2a2318;
    /* .emotions-modal__btn_new tiles paint entirely from this family; the dark tint
       keeps the "new" signal. */
    --reaction-popover-newDefault: #1d2615;
    --reaction-popover-newHover: #26331c;
    --reaction-popover-newClick: #47662e;
    --reaction-popover-newStroke: #3a4d2a;
    --reaction-donat-hover: #352c1e;
    --reaction-donat-click: #2e2b1f;
    /* .emotion-btn_active: the cream fill is the ONLY marker of your own reaction. */
    --reaction-activeDefault: #3a2f16;
    --reaction-activeHover: #4a3c1c;
    --reaction-activeClick: #5c4a22;
    --reaction-activeText: #f0b44f;

    /* The label on the theme's brand green is 5.1:1; Pikabu's own #78b247 is 3.7:1. */
    --story-btn-promote-default: #3a4d2a;
    --story-btn-promote-hover: #47662e;
    --story-btn-promote-click: #598039;
    --story-btn-promote-stroke: #598039;
    --story-btn-promote-content: var(--pk-green);

    /* All three truncation fades read these two: post body, .comment__show-all::before,
       .community-info-block__read-more::before. */
    --story-readMore-gradientA: var(--pk-surface);
    --story-readMore-gradientB: rgba(28, 33, 40, 0);

    /* ---- Pale semantic tints: near-white ramp ends used as SURFACES; dark-tune each,
       keep its hue ---- */
    --color-primary-100: #2a3a20;
    --color-primary-200: #2f4025;
    --color-danger-200: #2e1c1a;
    --color-warning-200: #2e2716;
    --color-blue-200: #16283a;
    --color-debate-light-first: #33201e;
    --color-debate-light-second: #1e2740;
    /* the labels on those two debate tints are saturated mid-tones, under 3:1 there */
    --color-debate-first: #ef6a5d;
    --color-debate-second: #8b96e8;

    /* The default fill is pinned neutral further down, so keep hover/press on the same
       ramp. */
    --gamification-btn-hover: var(--pk-surface);
    --gamification-btn-click: var(--pk-border);

    /* ---- Tags / chips / quotes / tooltips / menus ---- */
    --c-tag-bgDefault: var(--pk-surface-2);
    --c-tag-bgHover: var(--pk-surface);
    --c-tag-bgContrastDefault: var(--pk-surface-2);
    --c-tag-bgContrastHover: var(--pk-surface);
    --c-tag-stroke: var(--pk-border);
    --c-tag-strokeContrast: var(--pk-border);
    --c-quote-bg: var(--pk-surface-2);
    /* Tooltip NEUTRAL card = the `-base-` pair; `-secondary-` is already dark-carded. */
    --c-tooltip-base-bg: var(--pk-surface);
    --c-tooltip-base-text: var(--pk-text);
    --c-menu-item-text: var(--pk-text);
    --c-menu-item-hover: var(--pk-surface-2);
    --c-menu-item-click: var(--pk-border);
    --c-counter-bgTertiary: var(--pk-surface-2);
    /* Pikabu's #757880 is 3.4:1 on the dark-tuned pill above; this is its night value. */
    --c-counter-textTertiary: #dcdee5;
    /* filled counters keep a light brand/alert fill — flip their label dark to read */
    --c-counter-text: var(--pk-bg);

    /* ---- Secondary buttons (neutral greys) ---- */
    --c-btn-secondary-bgDefault: var(--pk-surface-2);
    --c-btn-secondary-bgHover: var(--pk-border);
    --c-btn-secondary-bgClick: var(--pk-border);
    --c-btn-secondary-textIcon: var(--pk-text-soft);
    --c-btnIcon-tertiary-bgDefault: var(--pk-surface-2);
    --c-btnIcon-tertiary-bgHover: var(--pk-surface);
    --c-btnIcon-tertiary-stroke: var(--pk-border);
    --c-btnSocialIcon-bgDefault: var(--pk-surface-2);
    --c-btnSocialIcon-bgHover: var(--pk-surface);
    --c-btnSocialIcon-bgClick: var(--pk-border);
    --c-social-bgWhite: var(--pk-surface);
    /* Plate behind each `.social-icon_square` glyph, a legacy :root grey Pikabu never
       dark-tunes. */
    --color-social-bg: var(--pk-surface-2);

    /* Split button neutral half: its LABEL token equals the fill colour, so the pill
       renders blank. */
    --c-btnSplit-secondary-textIcon: #b6b8bf;
    --c-btnSplit-secondary-bgHover: #757880;
    --c-btnSplit-secondary-bgClick: #909299;

    /* Despite its name --c-captcha-test-btn-bg is a `color` on the answer buttons. */
    --c-logo-text: #dcdee5;
    --c-captcha-block-link-default: #909299;
    --c-captcha-block-link-hover: #aaacb2;
    --c-captcha-block-link-click: #c2c5cc;
    --c-captcha-test-btn-bg: #909299;

    /* Cream pill under a grey label; Pikabu's own dark-amber family keeps the warm
       identity. */
    --c-btn-special-bgDefault: #4f4522;
    --c-btn-special-bgHover: #705d1c;
    --c-btn-special-bgClick: #937615;
    --c-btn-special-textIcon: #ebedf2;

    /* ---- Pagination ---- */
    --c-pagination-defaultBg: var(--pk-surface-2);
    --c-pagination-hoverBg: var(--pk-surface);
    --c-pagination-clickBg: var(--pk-border);
    --c-pagination-content: var(--pk-text-soft);
    /* The CURRENT page pill's label stays white, so its fill needs the deeper green,
       4.6:1. */
    --c-pagination-activeDefaultBg: var(--pk-green-shade);
    --c-pagination-activeHoverBg: #67993d;
    --c-pagination-activeClickBg: #6fa642;

    /* Drawn entirely in ::before (track) / ::after (knob) and fully token-driven. The
       knob goes dark to read in both states. */
    --c-switch-mainDefault: #5e6066;
    --c-switch-mainHover: #6b7480;
    --c-switch-mainClick: #7d8893;
    --c-switch-toggle: var(--pk-bg);
    --c-switch-activeDefault: var(--pk-green);
    --c-switch-activeHover: var(--pk-green-hover);
    --c-switch-activeClick: var(--pk-green-deep);

    /* Every glyph in the picker — month titles and all day numbers — reads
       --c-calendar-content; --c-calendar-choose is the in-range band. */
    --c-calendar-content: var(--pk-text-soft);
    --c-calendar-choose: #1d2615;
    --c-calendar-bgHover: rgba(255, 255, 255, 0.08);
    --c-calendar-bgClick: rgba(255, 255, 255, 0.16);
    --c-calendar-activeBgDefault: var(--pk-green-shade);
    --c-calendar-activeBgHover: #67993d;
    --c-calendar-activeBgClick: #6fa642;

    /* The track is one gradient: green up to the handle, --c-slider-lineBg past it. */
    --c-slider-lineBg: var(--pk-border);
    --c-slider-active: var(--pk-green);
    --c-slider-stokeHover: #26331c;
    --c-slider-stokeClick: #3a4d2a;

    /* Not a native scrollbar, so `color-scheme: dark` does not reach it. */
    --c-scrollbar-default: #45474d;
    --c-scrollbar-hover: #5e6066;
    --c-scrollbar-click: #757880;

    /* The checked mark is white, so its fill needs the deeper green. DISABLED must stay
       a step BELOW the default. */
    --c-checkbox-mainBgDefault: #5e6066;
    --c-checkbox-mainBgHover: #757880;
    --c-checkbox-mainBgClick: #909299;
    --c-checkbox-mainBgDisabled: #3a4149;
    --c-checkbox-mainStroke: #37393d;
    --c-checkbox-activeDefault: var(--pk-green-shade);
    --c-checkbox-activeHover: #67993d;
    --c-checkbox-activeClick: #6fa642;
    --c-radio-mainBgDefault: #5e6066;
    --c-radio-mainBgHover: #757880;
    --c-radio-mainBgClick: #909299;
    --c-radio-mainBgDisabled: #3a4149;
    --c-radio-mainStroke: #37393d;
    --c-radio-activeDefault: var(--pk-green-shade);
    --c-radio-activeHover: #67993d;
    --c-radio-activeClick: #6fa642;

    /* The ACTIVE bullet is left alone — it is the "you are here" marker. */
    --c-carouselBullets-medium-normal: #45474d;
    --c-carouselBullets-small-normal: #757880;

    /* The "rounded" variant fills near-white under a white --c-tab-roundedText label. */
    --c-tab-default: var(--pk-text-soft);
    --c-tab-hover: var(--pk-text);
    --c-tab-click: #ffffff;
    --c-tab-active: var(--pk-green);
    --c-tab-roundedBg: var(--pk-surface);

    /* VERTICAL navigation (profile side tabs) — separate family from `-horizontal-`. */
    --c-navigation-text: var(--pk-text-soft);
    --c-navigation-horizontal-textMainDefault: var(--pk-text-soft);
    --c-navigation-hover: var(--pk-surface);
    --c-navigation-active: var(--pk-surface);
    --c-navigation-click: var(--pk-border);

    /* Ghost ("text") button hover/press fills: pale-green and pale-pink washes. */
    --c-btn-primaryText-bgHover: #26331c;
    --c-btn-primaryText-bgClick: #1d2615;
    --c-btn-negativeText-bgHover: #2e1c1a;
    --c-btn-negativeText-bgClick: #3d211d;

    /* .pkb-normal-btn_negative-outline takes BOTH its ring and its label from these, and
       #cc4235 is 3.4:1 here. The ring also needs a selector rule further down — the
       blanket border reset outranks a :root remap. */
    --c-btn-negativeOutline-textStrokeDefault: #ef6a5d;
    --c-btn-negativeOutline-textStrokeHover: #f4837a;
    --c-btn-negativeOutline-textStrokeClick: #d9483b;
    /* Ghost sibling (.Btn__btn_negative-text) reads its own label token; same red. */
    --c-btn-negativeText-textIcon: #ef6a5d;

    /* Remaining light control fills. */
    --c-tag-bgClick: var(--pk-border);
    --c-tag-bgContrastClick: var(--pk-border);
    --c-tag-textContrast: var(--pk-text-soft);
    --c-btnIcon-tertiary-bgClick: var(--pk-border);
    --c-btnSplit-secondary-bgDefault: #5e6066;
    --c-btnIconSmall-disabled: #5e6066;

    /* These must move with --c-link-secondary-default, or hover drives the link back to
       near-black. */
    --c-link-secondary-hover: var(--pk-text);
    --c-link-secondary-click: var(--pk-text);
    --c-input-textFilled: var(--pk-text);
    --c-select-main-textSelected: var(--pk-text);
    --c-quote-text: var(--pk-text-soft);
    /* disabled tones must be DARKER than the enabled text, or disabled looks more
       active */
    --c-input-textDisabled: #5e6066;
    --c-input-iconDisabled: #5e6066;
    --c-select-main-textDisabled: #5e6066;
    --c-select-main-iconDisabled: #5e6066;
    --c-textarea-textDisabled: #5e6066;

    /* ---- Alerts / captcha / collapse ---- */
    --c-alert-baseBg: var(--pk-surface-2);
    --c-alert-baseStroke: var(--pk-border);
    /* Dark-tune each SEMANTIC alert variant while keeping its hue so severity reads. */
    --c-alert-accentBg: #1d2615;
    --c-alert-accentStroke: #3a4d2a;
    --c-alert-errorBg: #2e1c1a;
    --c-alert-errorStroke: #66120a;
    --c-alert-warningBg: #2e2716;
    --c-alert-warningStroke: #4f4522;
    --c-captcha-block-bg: var(--pk-surface-2);
    --c-captcha-block-stroke: var(--pk-border);
    /* the captcha's own answer buttons are a separate family from the block above */
    --c-captcha-test-btn-default: var(--pk-surface-2);
    --c-captcha-test-btn-hover: var(--pk-surface);
    --c-captcha-test-btn-click: var(--pk-border);
    --c-captcha-test-btn-stroke: var(--pk-border);
    --c-captcha-test-text: var(--pk-text-soft);
    --collapse-stroke: var(--pk-border);
    --c-bottomSheet-line: var(--pk-border);

    /* ---- Refine the brand green (keep hue family, lift for dark) ---- */
    --color-pikabu-80primary: var(--pk-green);
    --color-pikabu-75: var(--pk-green);
    --color-pikabu-60: var(--pk-green-deep);
    --color-primary-800: var(--pk-green);
    --color-primary-700: var(--pk-green);
    --color-primary-600: var(--pk-green);
    --color-primary-900: var(--pk-green-deep);
    --c-btn-primary-bgDefault: var(--pk-green);
    --c-btn-primary-bgHover: var(--pk-green-hover);
    --c-btn-primary-bgClick: var(--pk-green-deep);
    --c-btn-primaryText-textIcon: var(--pk-green);
    --c-navigation-horizontal-textActiveDefault: var(--pk-green);
    --c-counter-bgPrimary: var(--pk-green);
    --c-counter-textPrimary: var(--pk-green);
    --c-breadcrumbs-default: var(--pk-green);
    --s-colorTextSpecial-accent: var(--pk-green);

    /* ---- Rating: keep green up / red down, lift the tone for dark ---- */
    --rating-plus-active: var(--pk-green);
    --rating-plus-hover: var(--pk-green);
    --rating-plus-default: var(--pk-text-muted);
    --rating-plus-click: var(--pk-green-deep);
    --rating-minus-active: #ef6a5d;
    --rating-minus-hover: #ef6a5d;
    --rating-minus-default: var(--pk-text-muted);
    --rating-minus-click: #d9483b;
    --rating-progressMinus: #ef6a5d;
    --rating-icon: var(--pk-text-muted);
    --rating-text: var(--pk-text-muted);
    --rating-stroke: var(--pk-border);
    --rating-progressBg: var(--pk-border);
    --reaction-default: var(--pk-surface-2);
    --reaction-hover: var(--pk-surface);

    /* The EMPTY donate track reads --color-donate-bg; the green fill and the amount
       labels stay. */
    --color-donate-bg: var(--pk-border);

    /* ---- Mid-tone tokens under the floor on dark; each fixed with Pikabu's own night
       value ---- */

    /* #757880 = 3.66:1. */
    --s-icon-primary: #b6b8bf;
    --c-btnIcon-primary-textIcon: #909299;
    --c-btnIcon-tertiary-textIcon: #b6b8bf;
    /* same grey, same night value as the icon tokens above */
    --c-btn-secondaryText-textIcon: #909299;
    --sidebar-link-default: #909299;
    --sidebar-link-click: #aaacb2;
    --tabbar-contentDefault: #aaacb2;

    /* #e13d27 = 3.78:1 across 38 consumers (NSFW tag, form errors, ban icons, …). */
    --color-danger-900: #f75c48;

    /* Sole consumer is `.carousel__scroll svg { stroke }`, on a disc we darken to
       --pk-surface. */
    --color-contrast-bg: var(--pk-text);

    /* ---- Shadows ---- */
    --shadow-low: 0 1px 12px rgba(0, 0, 0, 0.4);
    /* Every ui-kit floating surface (ComboBox list, Select dropdown, date-range popover,
       menus, modal cards) draws its whole edge from this pair: a 1px `-Stroke` ring plus
       a blurred `main`/`extra` shadow. The ring must be LIGHT and visible — the surfaces
       share --pk-surface-2 with the inputs they open over, and a dark shadow reads as
       nothing there. */
    --s-shadow-mainStroke: rgba(255, 255, 255, 0.16);
    --s-shadow-extraStroke: rgba(255, 255, 255, 0.16);
    --s-shadow-main: rgba(0, 0, 0, 0.55);
    --s-shadow-extra: rgba(0, 0, 0, 0.65);
  }

  /* ===== Base canvas ===== */
  html { background-color: var(--pk-bg) !important; }
  body {
    background-color: var(--pk-bg) !important;
    color: var(--pk-text-soft) !important;
  }

  /* ===== Text selection =====
     Pikabu sets no selection colour and never dark-tunes its plate token. The
     -webkit-text-fill-color half is required: some components pin their own fill, which
     otherwise survives into the selection. */
  ::selection {
    background-color: #3a4d2a !important;
    color: var(--pk-text) !important;
    -webkit-text-fill-color: var(--pk-text) !important;
  }

  /* ===== Borders ===== (colour only — never adds a border, safe everywhere) */
  * { border-color: var(--pk-border) !important; }

  /* ===== Header ===== */
  .header,
  .header__inner,
  .header_with-ads,
  .app-header {
    background-color: var(--pk-header) !important;
    border-color: var(--pk-border) !important;
  }
  .header a,
  .header__nav a,
  .menu__link,
  .header-menu a { color: var(--pk-text-soft) !important; }
  .header a:hover,
  .menu__link:hover { color: var(--pk-text) !important; }
  /* Two of the three round green header buttons are <a>, so the `.header a` rule above
     repaints their glyph. */
  .header a.header-right-menu__add,
  .header a.header-right-menu__notification,
  .header a.header-right-menu__search {
    color: var(--pk-bg) !important;
  }
  .header-dropdown,
  .header-menu__dropdown,
  .menu-popup,
  .dropdown__content { background-color: var(--pk-surface) !important; }

  /* `.app__sidebar` keeps Pikabu's light #f5f5f5 panel. */
  .app__sidebar { background-color: var(--pk-bg) !important; }

  /* Each wordmark is an SVG on `currentColor` under a hardcoded `color: #222326`. The
     card fill reads --s-colorBg-tonned = our base canvas, so it needs the elevated surface
     to read as a tile. */
  .sidebar-products-temp__card {
    background-color: var(--pk-surface) !important;
    color: var(--pk-text) !important;
  }

  /* ===== Main columns / feed wrappers (transparent over base) ===== */
  .app,
  .layout,
  .layout__content,
  .main,
  .wrapper,
  .page,
  .page__inner,
  .stories-feed,
  .stories-feed__container,
  .feed,
  .sidebar,
  .sidebar_right,
  .sidebar_left { background-color: transparent !important; }

  /* ===== Story / post cards ===== */
  .story,
  .story__main,
  .story-block,
  .page-story,
  .page-story__main { background-color: var(--pk-surface) !important; }
  .story__title,
  .story__title-link,
  .story-title,
  .page-story__title { color: var(--pk-text) !important; }
  .story__content-inner,
  .story__text,
  .story-block__content,
  .b-story-block__text { color: var(--pk-text-soft) !important; }
  .story__title-link:hover { color: var(--pk-green-hover) !important; }

  /* The dim is the only read/unread signal on a feed card and our title rule above is
     !important, so restate it at (0,2,0). The post page keeps the title full strength. */
  .story__title-link.story__title-link_visited { color: var(--pk-text-muted) !important; }
  .page-story__story .story__title-link.story__title-link_visited { color: var(--pk-text) !important; }

  /* The author's colour is painted on .story__content-inner, so the nested text block
     must stay transparent. */
  [class*="story_primary"] .story-block,
  [class*="story_primary"] .story-block_type_text { background-color: transparent !important; }

  /* The author's plate stays saturated (--color-story-theme is a hue token we do not
     flip), where --pk-text-soft is 2.5:1. `bright-800` is the one plate painted from a
     neutral token, flipped dark here, so it keeps light ink. */
  .story_short .story__content-inner { color: #ffffff !important; }
  .story_short.story_bright-800 .story__content-inner { color: var(--pk-text) !important; }

  /* Rating block on the story card */
  .story__rating-block { background-color: var(--pk-surface-2) !important; }
  .story__rating-count { color: var(--pk-text-soft) !important; }

  /* ===== Tags ===== */
  .tags__tag,
  .story__tags a,
  a.tag {
    background-color: var(--pk-surface-2) !important;
    color: var(--pk-text-soft) !important;
    border-color: var(--pk-border) !important;
  }
  .tags__tag:hover,
  .story__tags a:hover { background-color: var(--pk-surface) !important; color: var(--pk-text) !important; }

  /* Tag STATE variants carry meaning; the selectors must outrank our own
     `.story__tags a` (0,1,1), hence the doubled forms. */
  .tags__tag.tags__tag_nsfw,
  .story__tags a.tags__tag_nsfw,
  a.tag_nsfw,
  .tags__tag.tags__tag_removed,
  .story__tags a.tags__tag_removed,
  a.tag_removed { color: #ef6a5d !important; }
  .tags__tag.tags__tag_added,
  .story__tags a.tags__tag_added,
  a.tag_added { color: var(--pk-green) !important; }
  /* Pikabu darkens the "[моё]" marker below the other tags, so inverted it must be
     lifted. Scoped off the skeleton row, which paints every tag transparent at the same
     (0,2,0). */
  .story__tags:not(.story__tags_skeleton) .tags__tag_highlight { color: var(--pk-text) !important; }

  /* ===== Comments tree ===== */
  .comments,
  .page-story__comments { background-color: var(--pk-surface) !important; }
  .comment,
  .comment__content,
  .comment__body { background-color: transparent !important; color: var(--pk-text-soft) !important; }
  .comment__user,
  .comment .user__nick { color: var(--pk-text) !important; }
  .comment-toolbar,
  .comments__sorting,
  .comment__children { background-color: transparent !important; }
  /* The guide-line is `.comment__children`'s own border-left; `.comment__branch` /
     `.comment__indent` / `.comment-thread__line` do not exist. */
  .comment__children { border-left-color: #4a525c !important; }

  /* Toggle + ring ENCODE STATE, and only the COLLAPSED variant is the green chip:
     rest -> grey ring + grey glyph; hover / collapse-strip hovered -> green ring + green
     glyph; `_collapse` -> green FILL + knockout glyph. The rest grey is a literal: this
     theme darkens --color-black-500, Pikabu's own source for it, to a divider tone. */
  .comment-toggle-children__icon {
    border-color: #6b7480 !important;
    color: var(--pk-text-muted) !important;
  }
  .comment-toggle-children:hover .comment-toggle-children__icon,
  .comment_collapsing-area > .comment-toggle-children > .comment-toggle-children__icon,
  .comment-toggle-children_collapse .comment-toggle-children__icon {
    border-color: var(--pk-green) !important;
    color: var(--pk-green) !important;
  }
  .comment-toggle-children_collapse .comment-toggle-children__icon { color: var(--pk-bg) !important; }
  /* Filled from --color-black-440 with a matching ring — not a green control. */
  .comment-hidden-group__toggle .comment-toggle-children__icon,
  .comment-toggle-children_only-hidden.comment-toggle-children_collapse .comment-toggle-children__icon {
    border-color: var(--pk-border) !important;
  }
  /* Hovering the collapse strip greens that subtree's guide-line to preview what will
     fold. */
  .comment_collapsing-area > .comment__children { border-left-color: var(--pk-green) !important; }

  /* --color-black-700 is a TEXT tone this theme lifts light, so the pill needs its own
     dark fill. */
  .comment__user[data-own="true"] .user__nick {
    background-color: #4a525c !important;
    color: var(--pk-text) !important;
  }

  /* Its own label token loses to the blanket !important .user__nick rule. */
  .comment__user[data-own-story="true"] .user__nick,
  .user_own .user__nick {
    color: var(--pk-bg) !important;
    -webkit-text-fill-color: var(--pk-bg) !important;
  }

  /* ===== Author / user blocks, avatars (do NOT tint the avatar image) ===== */
  .user__nick,
  .story__user-link,
  a.user { color: var(--pk-text) !important; }
  .avatar img,
  .user__avatar img,
  img.avatar { background-color: transparent !important; }

  /* ===== Search ===== */
  input[type="text"],
  input[type="search"],
  input[name="q"],
  .search-input,
  .input__field,
  textarea {
    background-color: var(--pk-surface-2) !important;
    color: var(--pk-text) !important;
    border-color: var(--pk-border) !important;
  }
  input::placeholder,
  textarea::placeholder { color: var(--pk-text-muted) !important; }
  .search-results,
  .search__results,
  .search-suggest { background-color: var(--pk-surface) !important; }

  /* ===== Login form — third-party provider buttons ===== */
  /* Pure white, not --pk-text: the brand fills are designed around white and --pk-text
     is a full step dimmer on the VK blue. */
  .auth__provider-text,
  [class*="auth__provider"] .auth__provider-text { color: #ffffff !important; }

  /* ===== Filter / sort / tab / segmented controls =====
     UNSELECTED labels are hardcoded near-blacks; the SELECTED state must stay
     distinct. */

  /* Home feed sort tabs (Горячее / Лучшее / Свежее / Подписки) */
  .header-menu__item,
  .header-menu__item a,
  .header-menu a { color: var(--pk-text-soft) !important; }
  .header-menu__item:hover,
  .header-menu__item:hover a { color: var(--pk-text) !important; }
  /* current/selected feed sort stays brand green + bolder */
  .header-menu__item_current,
  .header-menu__item_current a,
  .header-menu__item_active,
  .header-menu__item_active a { color: var(--pk-green) !important; font-weight: 600 !important; }
  /* Our hover rule (0,2,0) outranks the `_current` rule (0,1,0), so the current item
     needs its own hover rule. */
  .header-menu__item_current:hover,
  .header-menu__item_current:hover a,
  .header-menu__item_active:hover,
  .header-menu__item_active:hover a { color: var(--pk-green) !important; }

  /* Search result tabs (Посты / Пользователи / Теги / Сообщества) */
  [class*="TabItem__tab"],
  [class*="TabItem__tab"] span { color: var(--pk-text-soft) !important; }
  [class*="TabItem__tab"]:hover { color: var(--pk-text) !important; }
  /* The pill background is the tab's ::before pseudo. */
  [class*="TabItem__tab"]::before {
    background-color: var(--pk-surface-2) !important;
    border-color: var(--pk-border) !important;
  }
  [class*="TabItem__tab"]:hover::before { background-color: var(--pk-surface) !important; }
  /* The selected tab is marked by a data-tab-active ATTRIBUTE, not a class. */
  [class*="TabItem__tab"][data-tab-active],
  [class*="TabItem__tab"][data-tab-active] span { color: #ffffff !important; font-weight: 600 !important; }
  /* SHADE green, not ring green: --pk-green-deep under white is 2.7:1,
     --pk-green-shade 4.6:1. */
  [class*="TabItem__tab"][data-tab-active]::before {
    background-color: var(--pk-green-shade) !important;
    border-color: var(--pk-green-shade) !important;
  }
  /* A filled "primary" counter sits on brand green. The doubled attribute selector
     outranks the tab's own label rule. */
  [class*="Counter__host"][class*="_primary"],
  [class*="Counter__host"][class*="_primary"] span {
    color: var(--pk-bg) !important;
    -webkit-text-fill-color: var(--pk-bg) !important;
  }

  /* Search period / type segmented buttons (Сегодня / Неделя / Текстовые …) */
  [class*="SelectBtn__button"],
  [class*="SelectBtn__button"] span {
    background-color: var(--pk-surface-2) !important;
    color: var(--pk-text-soft) !important;
    border-color: var(--pk-border) !important;
  }
  [class*="SelectBtn__button"]:hover { background-color: var(--pk-surface) !important; color: var(--pk-text) !important; }
  /* the white label needs the SHADE green, the only one of our greens above 4.5:1 with
     white */
  [class*="SelectBtn__button_active"],
  [class*="SelectBtn__button_active"] span {
    background-color: var(--pk-green-shade) !important;
    color: #ffffff !important;
    border-color: var(--pk-green-shade) !important;
  }
  /* Pikabu draws NO hover state here, so the `:hover` rule above (0,2,0) outranks the
     `_active` fill (0,1,0). */
  [class*="SelectBtn__button_active"]:hover,
  [class*="SelectBtn__button_active"]:hover span {
    background-color: var(--pk-green-shade) !important;
    color: #ffffff !important;
    border-color: var(--pk-green-shade) !important;
  }

  /* Comment-sort + generic sorting controls (Лучшие / Новые / Старые …) */
  [class*="comments__sort"],
  [class*="comments__sort"] a,
  [class*="comments__sort"] span,
  [class*="sorting__item"],
  .comments__sorting a,
  .comments__sorting span { color: var(--pk-text-soft) !important; }
  [class*="sorting__item_active"],
  [class*="comments__sort"] .active,
  .comments__sorting .active { color: var(--pk-green) !important; font-weight: 600 !important; }

  /* The disabled tab's hardcoded near-black was a light grey on the light skin. */
  .menu__item_disabled,
  .menu__item_disabled span { color: var(--pk-text-muted) !important; }

  /* Only this accent/text variant; neutral Selects keep their token colours. */
  [class*="Select__host_text"] [class*="Select__label"] { color: var(--pk-green) !important; }

  /* Legacy sort control: label plus a Font Awesome ::before chevron, ~4.2:1 here. */
  span.link[data-role="sort"],
  span.link[data-role="sort"] span,
  span.link[data-role="sort"] i.fa { color: var(--pk-green) !important; }

  /* The #598039 label is ~2.9:1 here, and the outline's green border needs restoring
     too. */
  [class*="Btn__btn_primary-text"],
  [class*="Btn__btn_primary-text"] [class*="label"],
  [class*="Btn__btn_outline"],
  [class*="Btn__btn_outline"] [class*="label"] {
    color: var(--pk-green) !important;
    -webkit-text-fill-color: var(--pk-green) !important;
  }
  [class*="Btn__btn_outline"] { border-color: var(--pk-green-deep) !important; }

  /* An always-green outline button whose ring the universal border reset flattens. */
  .button.button_border,
  button.button_border,
  a.button_border {
    border-color: var(--pk-green-deep) !important;
    color: var(--pk-green) !important;
  }

  /* The border reset flattens the ring and `.header a` flattens the label — including
     the Apple glyph, an SVG on `currentColor`. */
  a.header__app-link,
  .header__app-link,
  .header a.header__app-link,
  .header a.header__app-link span {
    border-color: var(--pk-green-deep) !important;
    color: var(--pk-green) !important;
  }

  /* Identity lives in three COMPONENT-LOCAL properties on the element, out of reach of
     a :root flip. */
  .story-boost-badge {
    --story-boost-badge-bg: #26331c !important;
    --story-boost-badge-stroke: #598039 !important;
    --story-boost-badge-content: #8fd35c !important;
    background-color: var(--story-boost-badge-bg) !important;
    border-color: var(--story-boost-badge-stroke) !important;
    color: var(--story-boost-badge-content) !important;
  }

  /* Its shimmer gradient reads two component-local properties that stay near-white. */
  .loader-skeleton {
    --skeleton-mainGradA: #333b45 !important;
    --skeleton-mainGradB: #262c34 !important;
  }

  /* ===== Sidebar widgets / community blocks ===== */
  .sidebar-block,
  .sidebar-game,
  .community-card,
  .community,
  .b-community,
  .widget,
  .block { background-color: var(--pk-surface) !important; }
  .sidebar-block__title,
  .widget__title,
  .community-card__title { color: var(--pk-text) !important; }

  /* Literal values, not tokens, so they survive the :root flip. */
  .sidebar-game__title-text,
  .sidebar-game__name,
  .page-topic-links__name,
  .page-topic-links__title { color: var(--pk-text) !important; }
  .sidebar-game__title-subtext,
  .sidebar-game__genres { color: var(--pk-text-muted) !important; }

  /* Same near-black hardcoded on the title and the game names. */
  .feed-games-carousel__title-text,
  .feed-games-carousel__name { color: var(--pk-text) !important; }
  .feed-games-carousel__genres,
  .feed-games-carousel__subtext { color: var(--pk-text-muted) !important; }
  .page-topic-links,
  .page-topic-links__link {
    background-color: var(--pk-surface) !important;
    color: var(--pk-text-soft) !important;
  }
  .page-topic-links__link:hover { background-color: var(--pk-surface-2) !important; color: var(--pk-text) !important; }

  .gamification-btn { background-color: var(--pk-surface-2) !important; }

  /* #3a4d2a is Pikabu's own dark-theme value, scoped to :root[data-theme-dark] and so
     never applied here. */
  .daily-goal-badge { background-color: #3a4d2a !important; }

  /* Literal cream fill under a green label; the green label + ring keeps the donate
     identity. */
  .become-donator-btn {
    background-color: #1b2714 !important;
    color: var(--pk-green) !important;
    border-color: var(--pk-green-deep) !important;
  }

  /* `!important` on the custom property is required: Pikabu re-declares these under
     :root[data-theme-dark]. */
  .pkb-badge-shop {
    /* The BASE values are what a badge WITHOUT a colour variant resolves to (e.g.
       `_gray`). The six colour variants sit later at equal specificity, so they still
       win. */
    --badge-shop-bg: #262c34 !important;
    --badge-shop-stroke: #39414b !important;
    --badge-shop-content: #c4cdd6 !important;
    background-color: var(--badge-shop-bg) !important;
    border-color: var(--badge-shop-stroke) !important;
    color: var(--badge-shop-content) !important;
    -webkit-text-fill-color: var(--badge-shop-content) !important;
  }
  .pkb-badge-shop_myata {
    --badge-shop-bg: #11261f !important;
    --badge-shop-stroke: #1d4034 !important;
    --badge-shop-content: #5cb98a !important;
  }
  .pkb-badge-shop_bubblegum {
    --badge-shop-bg: #330d1d !important;
    --badge-shop-stroke: #4d142c !important;
    --badge-shop-content: #e5679c !important;
  }
  .pkb-badge-shop_papaya {
    --badge-shop-bg: #2e1707 !important;
    --badge-shop-stroke: #47240b !important;
    --badge-shop-content: #e58d4e !important;
  }
  .pkb-badge-shop_banana {
    --badge-shop-bg: #1f1d17 !important;
    --badge-shop-stroke: #332f23 !important;
    --badge-shop-content: #e8ba23 !important;
  }
  .pkb-badge-shop_berry {
    --badge-shop-bg: #121633 !important;
    --badge-shop-stroke: #1e254d !important;
    --badge-shop-content: #8b96e8 !important;
  }
  .pkb-badge-shop_sliva {
    --badge-shop-bg: #231233 !important;
    --badge-shop-stroke: #371d4d !important;
    --badge-shop-content: #b98be0 !important;
  }

  /* Pikabu darkens this cream pill only in its own dark theme. */
  button.emotion-btn_donated,
  .emotion-btn_donated {
    background-color: #2a2318 !important;
    color: #e0975a !important;
    -webkit-text-fill-color: #e0975a !important;
  }
  button.emotion-btn_donated:hover,
  .emotion-btn_donated:hover { background-color: #352c1e !important; }

  /* ===== Generic light surfaces caught by literal colours ===== */
  [style*="background: #fff"],
  [style*="background-color: #fff"],
  [style*="background:#fff"],
  [style*="background-color:#fff"] { background-color: var(--pk-surface) !important; }

  /* ===== Footer ===== */
  .footer,
  .page-footer,
  .b-footer {
    background-color: var(--pk-header) !important;
    color: var(--pk-text-muted) !important;
  }
  /* Scoped to the footer BLOCK: a `[class*="footer"] a` form also matches every
     `…__footer` sub-block, e.g. the games-carousel card footer's filled green CTA. */
  .footer a,
  .footer a span,
  .page-footer a,
  .b-footer a,
  [class*="footer__link"],
  [class*="footer-link"] { color: var(--pk-text-soft) !important; }
  /* A filled green button, so it keeps the dark label. */
  .footer a.pkb-normal-btn,
  .footer a.button_success,
  .page-footer a.pkb-normal-btn {
    color: var(--pk-bg) !important;
    -webkit-text-fill-color: var(--pk-bg) !important;
  }

  /* ===== Code / quotes inside posts ===== */
  pre, code, .b-story-block__code {
    background-color: var(--pk-surface-2) !important;
    color: #a5d6ff !important;
    border-color: var(--pk-border) !important;
  }
  blockquote, .b-quote, .comment__quote {
    background-color: var(--pk-surface-2) !important;
    border-color: var(--pk-border) !important;
    color: var(--pk-text-soft) !important;
  }
  /* /applications pins its own palette under :root[data-theme-apps-landing], a (0,2,0)
     block outranking our flip. */
  [data-theme-apps-landing] blockquote {
    background-color: transparent !important;
    color: var(--base-text-color) !important;
  }
  /* Same page: a deliberately WHITE card whose frame band and 1px dividers the border
     reset would darken. */
  .apps-landing-story__image { border-color: #ffffff !important; }
  .apps-landing-story__tags,
  .apps-landing-story__footer,
  .apps-landing-story > footer { border-color: #f3f4f5 !important; }

  /* ===== Generic muted / hint text =====
     `.hint` is NOT a muted-text class — it marks "this element owns a tooltip" and lands
     on shop badges, reaction pills and the logo. */
  .text-muted, .date, time, .comment__time, .story__date, .story__views {
    color: var(--pk-text-muted) !important;
  }

  /* A literal mid-grey rather than a token, below the floor on dark. */
  .story__comments-link-count,
  [class*="comments-link-count"],
  [class*="results-stories__count"],
  [class*="results-search__count"],
  [class*="Slider__info"] { color: var(--pk-text-muted) !important; }

  /* The ad disclosure hardcodes #6a6f76, ~3:1 on the dark surface. */
  .story__advert-info-text,
  [class*="advert-info-text"] { color: var(--pk-text-muted) !important; }

  /* Player poster placeholders show a light loading panel before the media paints. */
  [class*="player-block__preview"],
  [class*="video-file-player__player"],
  [class*="player-block__poster"] { background-color: #0d1117 !important; }
  /* Also matches the substring above, but it sits in the translucent state chip and
     must stay bare. */
  button[class*="player-block__previewSound"] { background-color: transparent !important; }

  /* --color-bright-900 is Pikabu's ALWAYS-white foreground, remapped dark at :root to
     read on our lightened greens. It also paints the chrome over photos, scrims and the
     black image viewer, so restore white there. --color-black-440 rides along on the
     viewer's icons. */
  .image-viewer,
  .external-video-viewer,
  .story__adult-overlay,
  .story_overlayed,
  /* the NSFW gate over a post's COMMENT section — same scrim, same token */
  .story-comments-nsfw-warning,
  .image-thumb__information,
  .image-thumb__duration,
  .story-fragment__play,
  .comment-external-video__play,
  .comment-external-video__state,
  .carousel_images .carousel__cur-slide,
  .dnd-overlay__content,
  /* --color-bright-900 is the halo lifting the heart off the photo */
  .comment__author-like,
  [class*="player-block__state"] {
    --color-bright-900: #e9e9e9;
    --color-black-440: #e9e9e9;
  }

  /* INVERTED TOKENS USED AS SURFACES. --color-black-700/-800/-900/-940 are DARK greys
     the flip lifts light (they are text colours nearly everywhere); a few places use them
     as a `background-color`:
     .image-viewer-loader__stage   lightbox spinner on the black scrim (#444850 natively)
     .popup_warning .popup__container  natively near-black (#212121) warning modal
     .comment-external-video__state:hover  hover fill on an embedded video's state chip
     .evaluation-emoji__title_framed / .avatar__note_banned / .icon--ui__close_story-preview
     video.player                  the legacy Vue player's letterbox area */
  .image-viewer-loader__stage,
  .evaluation-emoji__title_framed { background-color: #3a4149 !important; }
  .avatar__note_banned,
  .icon--ui__close_story-preview { background-color: var(--pk-border) !important; }
  video.player,
  .comment-external-video__state:hover { background-color: var(--pk-header) !important; }
  /* Its own text is --color-bright-900, remapped dark, so darkening the container alone
     leaves it dark-on-dark. */
  .popup_warning .popup__container {
    background-color: var(--pk-surface) !important;
    --color-bright-900: #e9e9e9;
  }

  /* These NEUTRAL members take their fill from an inverted token and their ink from
     --color-bright-900, so both ends move dark together. Their coloured siblings keep the
     dark ink correctly, so the restore must stay on the neutral member alone.
     `.evaluation-emoji__title_framed` sits on a plate pinned above, so its ink is
     --color-bright-800. */
  .story__quarantine-message_type_4,
  .story-diff .story__diff-marker_unchanged { --color-bright-900: #e9e9e9; }
  .evaluation-emoji__title_framed { --color-bright-800: #e9e9e9; }

  /* Popups land on --pk-surface, the same fill as the card they open over, and Pikabu's
     separating shadow only reads on a light page. `popup_modal` is excluded: there the
     container is a TRANSPARENT wrapper around two detached pieces, so a rim would trace
     empty space. */
  .popup:not(.popup_modal) .popup__container {
    border: 1px solid var(--pk-border) !important;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.6) !important;
  }

  /* Literal white background; loaded creatives paint over the darkened container. */
  .ads-placeholder,
  .external_branding,
  [class*="ads-placeholder"] { background-color: var(--pk-bg) !important; }

  /* Scope to `.promo-banner` exactly — NOT `.promo-banner-sticky`, the full-height
     wrapper. */
  .promo-banner { background-color: var(--pk-surface) !important; }

  /* The flip turns the marker's token-driven yellow plate a murky olive under
     near-black text. */
  .pkb-marker,
  mark,
  [class*="pkb-marker"] {
    background-color: #4a4327 !important;
    color: var(--pk-text) !important;
    -webkit-text-fill-color: var(--pk-text) !important;
  }

  /* --color-primary-200 is the pale-green ramp end the flip leaves untouched. */
  .pkb-highlight-block {
    background-color: #1b2714 !important;
    color: var(--pk-green) !important;
    border-color: var(--pk-green-deep) !important;
  }
  .pkb-highlight-block a { color: var(--pk-green) !important; }

  /* ===== Remaining literal light fills =====
     Out of reach of the :root flip; Pikabu darkens most only under
     :root[data-theme-dark]. */

  /* Fundraising "support" icon button on a post, and the profile "goal of the day"
     card. */
  /* The border reset flattens the ring, and the green outline plus green heart ARE the
     "support" affordance. */
  .pkb-donation-btn {
    background-color: #1d2615 !important;
    border-color: var(--pk-green-deep) !important;
  }
  .pkb-donation-btn:hover {
    background-color: #26331c !important;
    border-color: var(--pk-green) !important;
  }
  .gamification-daily-goal { background-color: #3a4d2a !important; }
  /* mobile header gamification pill */
  .mini-gamification-profile { background-color: #261306 !important; }

  /* Pale-lilac pill + dark purple label; keep the purple identity, inverted. */
  .story__promo .story-label {
    background-color: #2a1c33 !important;
    color: #b98be0 !important;
  }

  /* Placeholder card shown in place of a removed / unavailable post. */
  .story__gag_relative { background-color: var(--pk-surface) !important; }

  /* Cream fill plus `color: #212121 !important` (#454648 on mobile). The mobile sheet
     nests the block one level deeper, hence the second selector — it must match the site's
     specificity to win the !important tie. */
  .aflm .story-block_type_text div[data-content],
  .aflm .story__content-inner .story-block_type_text div[data-content] {
    background-color: var(--pk-surface-2) !important;
    color: var(--pk-text-soft) !important;
  }
  .aflm .story-block_type_text div[data-content] h1,
  .aflm .story-block_type_text div[data-content] h2,
  .aflm .story-block_type_text div[data-content] h3,
  .aflm .story__content-inner .story-block_type_text div[data-content] h1,
  .aflm .story__content-inner .story-block_type_text div[data-content] h2,
  .aflm .story__content-inner .story-block_type_text div[data-content] h3 {
    color: var(--pk-text) !important;
  }

  /* Power-rating (super +/−) picker buttons: hover/press flash a light grey. */
  .power-rating-modal__btn:hover,
  .power-rating-modal__btn:active { background-color: var(--pk-border) !important; }

  /* The arrow (--color-contrast-bg) is lifted light for the dark rest disc, so the
     pale-green --color-primary-400 hover fill would hide it. That token is shared with
     poll bars and the community progress fill and must stay pale. */
  .carousel__scroll:hover,
  .carousel__scroll:active,
  .gallery-viewer__icon-button:hover,
  .gallery-viewer__icon-button:active { background-color: #3a4d2a !important; }

  /* The glyph reads --color-bright-900, our DARK button ink — wrong on both the dark
     plate and the per-network hover fill. */
  .social-icon_square,
  .social-icon_round { --color-bright-900: #e9e9e9; }

  /* The small action inside each chip turns pure white on hover. */
  .items-list__item a:hover,
  .company-blog-search-panel__item a:hover,
  .stories-search-item a:hover,
  .items-list__close:hover { background-color: var(--pk-border) !important; }
  .items-list__more:hover { background-color: var(--pk-surface) !important; }

  /* The "..." story menu keeps a pure-white fill on the item that opened it. */
  .context-menu__item.story__dots_active { background-color: var(--pk-border) !important; }

  /* Counter pill in the vertical menus. The `_current` variant keeps its green fill. */
  .menu__counter {
    background-color: var(--pk-border) !important;
    color: var(--pk-text) !important;
  }

  /* A white capsule carrying a --color-black-700 label, which this theme lifts
     light. */
  .ex-scroller__body { background-color: var(--pk-surface) !important; }

  /* Darken the CONTAINER only; the artwork is untouched. */
  .sidebar__community-info img,
  .profile__promocode img { background-color: var(--pk-surface-2) !important; }

  /* The ring comes from a token, and the universal border reset outranks a :root
     remap. */
  .emotions-modal__btn_new { border-color: var(--reaction-popover-newStroke) !important; }
  .story__btn-promote { border-color: var(--story-btn-promote-stroke) !important; }
  .emotions-modal__alert { border-color: var(--c-alert-accentStroke) !important; }

  /* ===== Rings that ENCODE STATE, flattened by the universal border reset =====
     `* { border-color }` above is !important at (0,0,0): it loses to any class/attribute
     selector but beats every token remap. Pikabu writes !important on exactly two ring
     rules (legacy `.input:focus` / `.input_error`); every modern ui-kit control needs its
     ring restated here. */
  [class*="Input__host"]:focus-within,
  [class*="Textarea__host"]:focus-within,
  [class*="ComboBox__host_focused"],
  [class*="Select__host_open"] { border-color: var(--pk-green-deep) !important; }

  /* This ring is the ONLY error signal the component draws. */
  [class*="Input__host_error"],
  [class*="Textarea__host_error"],
  [class*="ComboBox__host_error"] { border-color: #e5594c !important; }

  /* Every thumbnail carries a 2px ring, so the accent ring is the ONLY "which image"
     signal. The checked radio is a green ring and nothing else. */
  .gallery-viewer__thumbnails .gallery-viewer__thumbnail-item_active,
  input:checked + .pkb-radio__handle { border-color: var(--pk-green) !important; }

  /* Destructive button — see the --c-btn-negativeOutline-* remap above. */
  .pkb-normal-btn_negative-outline { border-color: var(--c-btn-negativeOutline-textStrokeDefault) !important; }
  .pkb-normal-btn_negative-outline:hover { border-color: var(--c-btn-negativeOutline-textStrokeHover) !important; }
  .pkb-normal-btn_negative-outline:active { border-color: var(--c-btn-negativeOutline-textStrokeClick) !important; }

  /* Fills transparent with `border: 1px solid var(--text-color)`, so the whole
     affordance is the ring. */
  .pkb-normal-btn_border { border-color: var(--c-btn-primaryOutline-textStrokeDefault) !important; }
  .pkb-normal-btn_border:hover { border-color: var(--c-btn-primaryOutline-textStrokeHover) !important; }
  .pkb-normal-btn_border:active { border-color: var(--c-btn-primaryOutline-textStrokeClick) !important; }

  /* Unchecked, both background and colour are transparent, so the 1px ring IS the
     control. The CHECKED variants must follow at equal specificity or this rule flattens
     their green ring. */
  .checkbox,
  .radio { border-color: #5e6066 !important; }
  .checkbox_checked,
  .radio_checked { border-color: var(--pk-green) !important; }

  /* Its OFF track and knob tokens move the SAME direction here — 1.19:1, a featureless
     pill — so drive it from the ui-kit Switch tokens. `_checked` must follow: equal
     specificity, last one wins. */
  .checkbox_switch { background-color: var(--c-switch-mainDefault) !important; }
  .checkbox_switch.checkbox_checked { background-color: var(--c-switch-activeDefault) !important; }
  .checkbox_switch::after,
  .checkbox_switch.checkbox_checked::after { background-color: var(--c-switch-toggle) !important; }

  /* The ring is what makes it read as the "positive" variant. */
  [class*="pkb-tooltip-base__host_green"] [class*="pkb-tooltip-base__card"] { border-color: var(--pk-green-deep) !important; }

  /* Right for `_red` (a bright card), wrong for the dark-carded ones. `_dark` also
     fills from --color-black-900, an INVERTED token the flip turns near-white; fill and
     arrow both read --card-bg, so pin it on the host. */
  [class*="pkb-tooltip-base__host_green"],
  [class*="pkb-tooltip-base__host_dark"] { --color-bright-900: #e9e9e9; }
  [class*="pkb-tooltip-base__host_dark"] { --card-bg: var(--pk-surface) !important; }

  /* The card #fff and its #212121 text are literals, out of reach of the `.block`
     rule. */
  .content__numbers .block h3 { color: var(--pk-text) !important; }
  .content__numbers .block p { color: var(--pk-text-soft) !important; }

  /* Every selector MUST carry the #usedesk-widget prefix: the widget scopes its own
     rules to that mount id, so a plain — or even element-qualified — class selector loses
     the !important tie and paints nothing. Key off the `uw__` classes, never the `sc-*`
     hashes beside them, which rotate every build. The green header, avatar and submit
     button are the widget's brand and stay. */
  #usedesk-widget .uw__widget-layout__content { background-color: var(--pk-bg) !important; }
  #usedesk-widget .uw__chat-message-content { background-color: var(--pk-surface) !important; }
  #usedesk-widget .uw__chat-message-content,
  #usedesk-widget .uw__chat-message__text { color: var(--pk-text-soft) !important; }
  #usedesk-widget .uw__chat-message__date { color: var(--pk-text-muted) !important; }
  #usedesk-widget .uw__field-text,
  #usedesk-widget .uw__field__select,
  #usedesk-widget .uw__field-textarea {
    background-color: var(--pk-surface-2) !important;
    color: var(--pk-text) !important;
    border-color: var(--pk-border) !important;
  }
  #usedesk-widget .uw__field-text::placeholder,
  #usedesk-widget .uw__field-textarea::placeholder { color: var(--pk-text-muted) !important; }
  #usedesk-widget .uw__footer {
    background-color: var(--pk-surface-2) !important;
    color: var(--pk-text-muted) !important;
  }
  /* The composer's own <textarea> carries only rotating hashes, so hook it through the
     bar. */
  #usedesk-widget .uw__chat-content { background-color: var(--pk-bg) !important; }
  #usedesk-widget .uw__chat-form { background-color: var(--pk-surface-2) !important; }
  #usedesk-widget .uw__chat-form textarea {
    background-color: transparent !important;
    color: var(--pk-text) !important;
  }
  #usedesk-widget .uw__chat-form textarea::placeholder { color: var(--pk-text-muted) !important; }
  #usedesk-widget .uw__chat-form .uw__icon { filter: invert(1) brightness(0.85) !important; }
  /* A remote black-linework SVG background-image. The header's close glyph is a white
     data-URI on the green bar and must NOT be inverted, hence the scope. */
  #usedesk-widget .uw__file-loader .uw__icon { filter: invert(1) brightness(0.85) !important; }

  /* Red and blue mid-tone labels fall under the floor on these tints; green and amber
     clear it. */
  .pkb-badge_highlight { color: var(--pk-green) !important; }
  .pkb-profile-rating-counter_red { color: #ef6a5d !important; }
  .company-blog-badge { color: #45b6dd !important; }

  /* --color-black-940 ink on a kept --color-warning-900 plate is ~1.5:1. The plate is
     the signal, so the label goes dark instead. */
  .toast_warning,
  .pls-not-block_warning,
  .auth__msg_warning,
  .auth-modal__notice { color: var(--pk-bg) !important; }
}
